package com.arjunren.leave.controller;
import com.arjunren.leave.domain.*;import com.arjunren.leave.dto.Dtos.*;import com.arjunren.leave.entity.AppUser;import com.arjunren.leave.service.LeaveService;import jakarta.validation.Valid;import java.util.Map;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api")public class LeaveController{private final LeaveService leaves;public LeaveController(LeaveService l){leaves=l;}@PostMapping("/employees")@ResponseStatus(HttpStatus.CREATED)Map<String,Object>createEmployee(@Valid@RequestBody EmployeeCreate r,@AuthenticationPrincipal AppUser u){return Map.of("data",leaves.createEmployee(r,u));}@GetMapping("/employees")Map<String,Object>employees(@AuthenticationPrincipal AppUser u,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return Map.of("data",leaves.employees(u,page,Math.min(Math.max(size,1),100)));}@PostMapping("/leave-requests")@ResponseStatus(HttpStatus.CREATED)Map<String,Object>request(@Valid@RequestBody LeaveCreate r,@AuthenticationPrincipal AppUser u){return Map.of("data",leaves.request(r,u));}@GetMapping("/leave-requests")Map<String,Object>list(@AuthenticationPrincipal AppUser u,@RequestParam(required=false)LeaveStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return Map.of("data",leaves.list(u,status,page,Math.min(Math.max(size,1),100)));}@PatchMapping("/leave-requests/{id}/approve")Map<String,Object>approve(@PathVariable Long id,@Valid@RequestBody DecisionRequest r,@AuthenticationPrincipal AppUser u){return Map.of("data",leaves.approve(id,r.note(),u));}@PatchMapping("/leave-requests/{id}/reject")Map<String,Object>reject(@PathVariable Long id,@Valid@RequestBody DecisionRequest r,@AuthenticationPrincipal AppUser u){return Map.of("data",leaves.reject(id,r.note(),u));}@PatchMapping("/leave-requests/{id}/cancel")Map<String,Object>cancel(@PathVariable Long id,@AuthenticationPrincipal AppUser u){return Map.of("data",leaves.cancel(id,u));}@GetMapping("/dashboard")Map<String,Object>dashboard(@AuthenticationPrincipal AppUser u){if(u.getRole()==Role.ADMIN)return Map.of("data",Map.of("pending",leaves.count(LeaveStatus.PENDING),"approved",leaves.count(LeaveStatus.APPROVED)));return Map.of("data",leaves.list(u,null,0,100));}}

